        }
        RefuseRetiredInput.check(to, claim.date());
        Claim moved = claims.reassign(claim, to.id());
        if (moved == null) {
            throw new ClaimReassignRefusedException("The claim has changed since it was loaded.");
        }
        responseOut.set(ClaimResponse.from(moved));
        toOut.set(to);
    }
