61	
62	/** Works out a sheet's figures the way the screen shows them (claimed, due-total, overdue-total, and their totals). */
63	@Service
64	public class Rollup {
65	
66	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
67	
68	    private final People people;
69	    private final Claims claims;
70	    private final Rates rates;
71	    private final Sheets sheets;
72	    private final Settings settings;
73	
74	    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings) {
75	        this.people = people;
76	        this.claims = claims;
77	        this.rates = rates;
78	        this.sheets = sheets;
79	        this.settings = settings;
80	    }
81	
82	    public Figures figures(String sheetId) {
83	        LocalDate today = sheets.today(sheetId);
84	        List<Claim> counting = claims.list(sheetId).stream()
85	                .filter(c -> c.status().counts()).toList();
86	        Map<Long, Figures.PersonFigures> figures = new LinkedHashMap<>();
87	        BigDecimal claimedTotal = ZERO;
88	        List<BigDecimal> dues = new ArrayList<>();
89	        List<BigDecimal> overdues = new ArrayList<>();
90	        for (Person person : people.list(sheetId)) {
91	            BigDecimal claimed = ZERO;
92	            BigDecimal due = ZERO;
93	            BigDecimal overdue = ZERO;
94	            boolean anyFigure = false;
95	            for (Claim claim : counting) {
96	                if (claim.personId() != person.id() || !counts(claim, person, today)) {
97	                    continue;
98	                }
99	                claimed = claimed.add(claim.amount());
100	                BigDecimal figure = figure(claim, person, today);
101	                if (figure != null) {
102	                    due = due.add(figure);
103	                    anyFigure = true;
104	                    if (settings.overdue(claim, today)) {
105	                        overdue = overdue.add(figure);
106	                    }
107	                }
108	            }
109	            // With no rate today and no figure, the due-total is n/a.
110	            boolean none = !anyFigure && rates.on(sheetId, person.gradeOn(today), today) == null;
111	            // Otherwise it is held to the sheet's cap.
112	            due = settings.capped(sheetId, due);
113	            claimedTotal = claimedTotal.add(claimed);
114	            if (!none) {
115	                dues.add(due);
116	            }
117	            overdues.add(overdue);
118	            figures.put(person.id(), new Figures.PersonFigures(person.name(), claimed.toPlainString(),
119	                    none ? "n/a" : due.toPlainString(), overdue.toPlainString()));
120	        }
121	        return new Figures(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
122	                trimmed(overdues).toPlainString());
123	    }
124	
125	    /** A sheet total of per-person figures: with three or more, the single highest and lowest are left out. */
126	    private static BigDecimal trimmed(List<BigDecimal> figures) {
127	        List<BigDecimal> sorted = figures.stream().sorted().toList();
128	        List<BigDecimal> kept = sorted.size() >= 3 ? sorted.subList(1, sorted.size() - 1) : sorted;
129	        return kept.stream().reduce(ZERO, BigDecimal::add);
130	    }
131	
132	    /**
133	     * Each person's due-total for the dates {@code from} to {@code to} inclusive, by person id in sheet order: the
134	     * figures (as shown now) of their claims due by a date then that counted by the status their log records at the end of
135	     * {@code to} (a claim added after it counts not at all), those without one skipped.
136	     */
137	    public Map<Long, BigDecimal> personDueTotals(String sheetId, LocalDate from, LocalDate to) {
138	        LocalDate today = sheets.today(sheetId);
139	        Map<Long, ClaimStatus> ended = claims.statusesOn(sheetId, to);
140	        List<Claim> dated = claims.list(sheetId).stream()
141	                .filter(c -> !c.dueBy().isBefore(from) && !c.dueBy().isAfter(to)).toList();
142	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
143	        for (Person person : people.list(sheetId)) {
144	            BigDecimal total = ZERO;
145	            for (Claim claim : dated) {
146	                Claim then = claim.withStatus(ended.getOrDefault(claim.id(), claim.status()), claim.number(),
147	                        claim.settledDue(), claim.openedBy());
148	                // A hold leaves out only a claim that is open now.
149	                boolean left = claim.status().isOpen() ? !counts(then, person, today) : then.deferredOn(today);
150	                if (claim.personId() != person.id() || !then.status().counts() || left) {
151	                    continue;
152	                }
153	                BigDecimal figure = figure(claim, person, today);
154	                if (figure != null) {
155	                    total = total.add(figure);
156	                }
157	            }
158	            totals.put(person.id(), total);
159	        }
160	        return totals;
161	    }
162	
163	    /** The claim's figure as the screen shows it on the sheet's today (null: n/a), whatever its status. */
164	    public BigDecimal figure(Claim claim) {
165	        Person person = people.find(claim.sheetId(), claim.personId());
166	        return person == null ? claim.settledDue() : figure(claim, person, sheets.today(claim.sheetId()));
167	    }
168	
169	    /**
170	     * Whether the (OPEN, PENDING or SETTLED) claim counts: a person's open claims dated within one of their holds
171	     * count in no live total, unless a statement bound them, nor do they once {@code today} reaches their retirement date;
172	     * nor does an OPEN claim deferred on {@code today}.
173	     */
174	    public static boolean counts(Claim claim, Person person, LocalDate today) {
175	        if (claim.deferredOn(today)) {
176	            return false;
177	        }
178	        boolean bound = claim.stated() && claim.status() != ClaimStatus.PENDING;
179	        return !(claim.status().isOpen() && !bound && (person.heldOn(claim.date()) || person.retiredOn(today)));
180	    }
181	
182	    /**
183	     * The claim's figure (null when it has none): a settled claim's frozen due, otherwise the figure its person's
184	     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, rounded by the policy date;
185	     * an overdue claim's late charge on {@code today} added on top of the last two, then raised to the floor.
186	     */
187	    private BigDecimal figure(Claim claim, Person person, LocalDate today) {
188	        if (claim.settledDue() != null) {
189	            return claim.settledDue();
190	        }
191	        return settings.withLate(claim, bound(claim, person), today);
192	    }
193	
194	    /**
195	     * The claim's figure before any late charge: the one its person's last statement bound, else its live rate figure (not floored).
196	     * A PENDING claim is not bound: it shows its live figure until approved or rejected.
197	     */
198	    private BigDecimal bound(Claim claim, Person person) {
199	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
200	            return claim.statedDue();
201	        }
202	        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
203	        return settings.live(claim, rate);
204	    }
205	}
