291	                .filter(r -> r.grade().equals(grade) && (r.from() == null || !r.from().isAfter(date)))
292	                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
293	                .filter(r -> r.to() == null || !r.to().isBefore(date))
294	                .map(Rate::rate).orElse(null);
