301	public class ValidateRate {
302	
303	    private static final Set<String> GRADES = Set.of("A", "B", "C");
304	    private static final Pattern PERCENT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");
305	    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
306	            .withResolverStyle(ResolverStyle.STRICT);
307	
308	    // The rate is kept with two decimals; a grade other than A, B or C, or a rate that is not a
309	    // percent of 0.00 or more with up to two decimals, is refused. A blank from-date means from the
310	    // beginning of time; one that is not a date (yyyy-mm-dd) is refused. A blank to-date means with no end; one
311	    // that is not a date, or is before the from-date, is refused.
312	    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("grade") String grade,
313	            @RequestBody RateRequest body, Out<Rate> rateOut) throws InvalidRateException {
314	        String g = grade == null ? "" : grade.trim();
315	        String typed = body == null || body.rate() == null ? "" : body.rate().trim();
316	        if (!GRADES.contains(g)) {
317	            throw new InvalidRateException("The grade must be A, B or C.");
318	        }
319	        if (!PERCENT.matcher(typed).matches()) {
320	            throw new InvalidRateException("The rate must be a percent of 0.00 or more, with up to two decimals.");
321	        }
322	        String typedFrom = body == null || body.from() == null ? "" : body.from().trim();
323	        LocalDate from = null;
324	        if (!typedFrom.isEmpty()) {
325	            try {
326	                from = LocalDate.parse(typedFrom, ISO);
327	            } catch (DateTimeParseException e) {
328	                throw new InvalidRateException("The from-date must be a date (yyyy-mm-dd).");
329	            }
330	        }
331	        String typedTo = body == null || body.to() == null ? "" : body.to().trim();
332	        LocalDate to = null;
333	        if (!typedTo.isEmpty()) {
334	            try {
335	                to = LocalDate.parse(typedTo, ISO);
336	            } catch (DateTimeParseException e) {
337	                throw new InvalidRateException("The to-date must be a date (yyyy-mm-dd).");
338	            }
339	            if (from != null && to.isBefore(from)) {
340	                throw new InvalidRateException("The to-date must not be before the from-date.");
341	            }
342	        }
343	        rateOut.set(new Rate(sheetId.trim(), g, new BigDecimal(typed).setScale(2, RoundingMode.UNNECESSARY), from, to));
344	    }
345	}
